-- =============================================================================================
-- Generated by `mj sync push --dir metadata --ci --include=authorizations,authorization-roles`
-- (MJ CLI 6.2.1) against a database built from migrations ONLY: MJ core v6.2.1, then
-- bizapps-common, -tasks, -accounting, -contracts and -sales at their released `main`, then this
-- app's migrations at `next`. The two folders are the only metadata changed since v5.47.1.
-- Push result: 3 created, 0 errors.
--
-- CREATED (bc-aidp-next-golive#454):
--   Authorization        MJ.BizApps.Orders.Order.Reverse
--   Authorization Roles  Finance -> Order.Reverse; Developer -> Order.Reverse (Allow)
-- Without the authorization, cancelling a subscription, refunding a payment, moving an account
-- credit and lowering an agreed amount are refused.
--
-- CREATE-ONLY: each create is guarded on its ID or its natural key (Name; AuthorizationID +
-- RoleID), and the push log's update branches are cut, so a host's later changes are kept. The
-- authorization and roles resolve by Name.
--
-- TRANSFORMS: `[${mjSchema}].` -> `[${mjSchema}].`; string values untouched. Idempotent.
-- =============================================================================================

-- Save MJ: Authorizations (core SP call only)
DECLARE @ID_fb6175fbdcb3 UNIQUEIDENTIFIER,
@ParentID_fb6175fbdcb3 UNIQUEIDENTIFIER,
@Name_fb6175fbdcb3 NVARCHAR(100),
@IsActive_fb6175fbdcb3 BIT,
@UseAuditLog_fb6175fbdcb3 BIT,
@Description_fb6175fbdcb3 NVARCHAR(MAX)
SET
  @ID_fb6175fbdcb3 = 'B1743944-D373-4F8E-A5CE-0FE96F38B9D9'
SET
  @Name_fb6175fbdcb3 = N'MJ.BizApps.Orders.Order.Reverse'
SET
  @IsActive_fb6175fbdcb3 = 1
SET
  @UseAuditLog_fb6175fbdcb3 = 1
SET
  @Description_fb6175fbdcb3 = N'Reverse money a booked order holds: cancel a subscription (Orders.CancelSubscription, with its credit memo), refund a payment (Orders.RefundPayment), move an account credit to another order (Orders.ApplyAccountCredit), or lower an agreed amount (Orders.AmendArrangement with NewAmount). Each refuses a caller without it, before any read or write; a record of something the payment gateway already did is exempt. Held by the Finance role, and by Developer, which keeps every permission (bc-aidp-next-golive#454). A return (a reversal order booked from the Returns page) does not need it. Without this row, all four are refused.'
IF NOT EXISTS (SELECT 1 FROM [${mjSchema}].[Authorization]
               WHERE [ID] = @ID_fb6175fbdcb3
                  OR ([Name] = @Name_fb6175fbdcb3))
BEGIN
EXEC [${mjSchema}].spCreateAuthorization @ID = @ID_fb6175fbdcb3,
  @ParentID = @ParentID_fb6175fbdcb3,
  @ParentID_Clear = 1,
  @Name = @Name_fb6175fbdcb3,
  @IsActive = @IsActive_fb6175fbdcb3,
  @UseAuditLog = @UseAuditLog_fb6175fbdcb3,
  @Description = @Description_fb6175fbdcb3
END;

GO

-- Save MJ: Authorization Roles (core SP call only)
DECLARE @ID_5a07d0055a4e UNIQUEIDENTIFIER,
@AuthorizationID_5a07d0055a4e UNIQUEIDENTIFIER,
@RoleID_5a07d0055a4e UNIQUEIDENTIFIER,
@Type_5a07d0055a4e NCHAR(10)
SET
