SET
  @AuthorizationID_5a07d0055a4e = (
    SELECT
      [ID]
    FROM
      [${mjSchema}].[Authorization]
    WHERE
      LOWER([Name]) = LOWER(N'MJ.BizApps.Orders.Order.Reverse')
  )
SET
  @RoleID_5a07d0055a4e = (
    SELECT
      [ID]
    FROM
      [${mjSchema}].[Role]
    WHERE
      LOWER([Name]) = LOWER(N'Finance')
  )
SET
  @Type_5a07d0055a4e = N'Allow'
IF NOT EXISTS (SELECT 1 FROM [${mjSchema}].[AuthorizationRole]
               WHERE [ID] = @ID_5a07d0055a4e
                  OR ([AuthorizationID] = @AuthorizationID_5a07d0055a4e AND [RoleID] = @RoleID_5a07d0055a4e))
BEGIN
EXEC [${mjSchema}].spCreateAuthorizationRole @ID = @ID_5a07d0055a4e,
  @AuthorizationID = @AuthorizationID_5a07d0055a4e,
  @RoleID = @RoleID_5a07d0055a4e,
  @Type = @Type_5a07d0055a4e
END;

GO

